CREATE OR REPLACE FUNCTION public.admin_vehicle_records(_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; RETURN (SELECT coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) FROM (SELECT id,user_id,vehicle_type,vehicle_name,vehicle_number,driver_name,contact_phone,from_place,to_place,trip_date,status,created_at FROM public.posts WHERE module='vehicle' ORDER BY id LIMIT 500 OFFSET greatest(0,_offset)) v); END $$;
REVOKE ALL ON FUNCTION public.admin_vehicle_records(integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_vehicle_records(integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.mark_my_vehicle_booked(_post uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; UPDATE public.posts SET status='closed' WHERE id=_post AND user_id=auth.uid() AND module='vehicle' AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'OWN_ACTIVE_VEHICLE_REQUIRED'; END IF; END $$;
REVOKE ALL ON FUNCTION public.mark_my_vehicle_booked(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mark_my_vehicle_booked(uuid) TO authenticated;
CREATE TABLE public.service_priority_applications(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),area text NOT NULL,category text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.service_priority_applications TO authenticated; GRANT ALL ON public.service_priority_applications TO service_role;
ALTER TABLE public.service_priority_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_priority_read ON public.service_priority_applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.apply_service_priority(_area text,_category text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) OR NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF length(trim(_area)) NOT BETWEEN 1 AND 80 OR length(trim(_category)) NOT BETWEEN 1 AND 100 OR NOT EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=auth.uid() AND member_kind='service') THEN RAISE EXCEPTION 'SERVICE_PROFILE_REQUIRED'; END IF; INSERT INTO public.service_priority_applications(user_id,area,category) VALUES(auth.uid(),trim(_area),trim(_category)) ON CONFLICT(user_id) DO UPDATE SET area=excluded.area,category=excluded.category,applied_at=now(); END $$;
REVOKE ALL ON FUNCTION public.apply_service_priority(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.apply_service_priority(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.service_priority_position(_user uuid,_area text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT rank_no::integer FROM (SELECT user_id,row_number() OVER(ORDER BY applied_at,user_id) rank_no FROM public.service_priority_applications WHERE lower(trim(area))=lower(trim(_area)) AND public.has_paid_bell(user_id) AND public.account_allowed(user_id)) s WHERE user_id=_user AND rank_no<=10 $$;
REVOKE ALL ON FUNCTION public.service_priority_position(uuid,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_service_priority(_area text,_category text DEFAULT '') RETURNS TABLE(id text,source text,category text,area text,priority integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF; RETURN QUERY SELECT w.id,w.source,w.category,w.area,coalesce(public.service_priority_position(CASE WHEN w.source='provider' THEN w.id::uuid WHEN w.source='entry' THEN (SELECT user_id FROM public.free_work_entries WHERE free_work_entries.id=w.id::uuid) WHEN w.source='post' THEN (SELECT user_id FROM public.posts WHERE posts.id=w.id::uuid) END,w.area),0) FROM public.list_free_work('service-providers',_area,_category) w ORDER BY CASE WHEN public.service_priority_position(CASE WHEN w.source='provider' THEN w.id::uuid WHEN w.source='entry' THEN (SELECT user_id FROM public.free_work_entries WHERE free_work_entries.id=w.id::uuid) WHEN w.source='post' THEN (SELECT user_id FROM public.posts WHERE posts.id=w.id::uuid) END,w.area) IS NULL THEN 1 ELSE 0 END,w.id; END $$;
REVOKE ALL ON FUNCTION public.list_service_priority(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_service_priority(text,text) TO authenticated;